// trace_rustc_main.rs - Trace complete dependency tree for rustc main
// Generated by step4_bootstrap - Rustc Main Dependency Tree

use split_decls_genesis::{
    extract_all_symbols_from_file_fast, resolve_qualified_dependency
};
use std::collections::{HashMap, HashSet, VecDeque};
use serde_json;

fn main() {
    println!("🔍 Tracing complete dependency tree for rustc main...");
    
    // Load our complete symbol map
    let symbol_map = load_symbol_map();
    println!("✅ Loaded {} symbols", symbol_map.len());
    
    // Find rustc main function
    let rustc_main = find_rustc_main(&symbol_map);
    
    match rustc_main {
        Some((main_name, main_symbol)) => {
            println!("🎯 Found rustc main: {} in {}", main_name, main_symbol.source_file);
            println!("   Type: {}", main_symbol.symbol_type);
            println!("   Direct dependencies: {}", main_symbol.dependencies.len());
            
            // Trace complete dependency tree
            let dep_tree = trace_dependency_tree(&main_name, &symbol_map, 100);
            
            println!("\n📊 RUSTC MAIN DEPENDENCY TREE:");
            println!("  🌳 Total dependencies: {}", dep_tree.len());
            println!("  📈 Max depth reached: {}", calculate_max_depth(&dep_tree));
            
            // Show dependency levels
            show_dependency_levels(&main_name, &symbol_map, 5);
            
            // Show resolved vs unresolved
            analyze_resolution_status(&main_symbol.dependencies, &symbol_map);
            
            // Export full tree
            export_dependency_tree(&main_name, &dep_tree);
            
        },
        None => {
            println!("❌ No rustc main function found");
            
            // Show what main functions we do have
            let main_functions: Vec<_> = symbol_map.iter()
                .filter(|(name, _)| name.as_str() == "main")
                .collect();
            
            println!("📋 Available main functions ({}):", main_functions.len());
            for (name, symbol_json) in main_functions.iter().take(10) {
                if let Ok(symbol) = parse_symbol(symbol_json) {
                    println!("  - {} in {} ({})", name, symbol.source_file, symbol.crate_name);
                }
            }
        }
    }
}

fn load_symbol_map() -> HashMap<String, serde_json::Value> {
    match std::fs::read_to_string("symbol_map.json") {
        Ok(content) => {
            serde_json::from_str(&content).unwrap_or_default()
        },
        Err(_) => {
            println!("⚠️  symbol_map.json not found, generating...");
            HashMap::new()
        }
    }
}

fn find_rustc_main(symbol_map: &HashMap<String, serde_json::Value>) -> Option<(String, RustcSymbol)> {
    // Look for main function in rustc crate
    for (name, symbol_json) in symbol_map {
        if name == "main" {
            if let Ok(symbol) = parse_symbol(symbol_json) {
                if symbol.crate_name == "rustc" || symbol.source_file.contains("rustc") {
                    return Some((name.clone(), symbol));
                }
            }
        }
    }
    
    // Fallback: any main function
    for (name, symbol_json) in symbol_map {
        if name == "main" {
            if let Ok(symbol) = parse_symbol(symbol_json) {
                return Some((name.clone(), symbol));
            }
        }
    }
    
    None
}

#[derive(Debug, Clone)]
struct RustcSymbol {
    name: String,
    symbol_type: String,
    source_file: String,
    crate_name: String,
    dependencies: Vec<String>,
}

fn parse_symbol(json: &serde_json::Value) -> Result<RustcSymbol, ()> {
    Ok(RustcSymbol {
        name: json["name"].as_str().unwrap_or("").to_string(),
        symbol_type: json["symbol_type"].as_str().unwrap_or("").to_string(),
        source_file: json["source_file"].as_str().unwrap_or("").to_string(),
        crate_name: json["crate_name"].as_str().unwrap_or("").to_string(),
        dependencies: json["dependencies"].as_array()
            .map(|arr| arr.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect())
            .unwrap_or_default(),
    })
}

fn trace_dependency_tree(
    root: &str, 
    symbol_map: &HashMap<String, serde_json::Value>, 
    max_depth: usize
) -> HashMap<String, usize> {
    let mut visited = HashMap::new();
    let mut queue = VecDeque::new();
    
    queue.push_back((root.to_string(), 0));
    visited.insert(root.to_string(), 0);
    
    while let Some((symbol_name, depth)) = queue.pop_front() {
        if depth >= max_depth {
            continue;
        }
        
        if let Some(symbol_json) = symbol_map.get(&symbol_name) {
            if let Ok(symbol) = parse_symbol(symbol_json) {
                for dep in &symbol.dependencies {
                    if !visited.contains_key(dep) {
                        visited.insert(dep.clone(), depth + 1);
                        queue.push_back((dep.clone(), depth + 1));
                    }
                }
            }
        }
    }
    
    visited
}

fn calculate_max_depth(dep_tree: &HashMap<String, usize>) -> usize {
    dep_tree.values().max().copied().unwrap_or(0)
}

fn show_dependency_levels(
    root: &str,
    symbol_map: &HashMap<String, serde_json::Value>,
    max_levels: usize
) {
    println!("\n🌊 DEPENDENCY LEVELS:");
    
    if let Some(symbol_json) = symbol_map.get(root) {
        if let Ok(_symbol) = parse_symbol(symbol_json) {
            println!("  Level 0 (Root): {}", root);
            
            for level in 1..=max_levels {
                let level_deps = get_dependencies_at_level(root, symbol_map, level);
                if !level_deps.is_empty() {
                    println!("  Level {}: {} dependencies", level, level_deps.len());
                    for (i, dep) in level_deps.iter().take(5).enumerate() {
                        println!("    {}. {}", i + 1, dep);
                    }
                    if level_deps.len() > 5 {
                        println!("    ... and {} more", level_deps.len() - 5);
                    }
                }
            }
        }
    }
}

fn get_dependencies_at_level(
    root: &str,
    symbol_map: &HashMap<String, serde_json::Value>,
    target_level: usize
) -> Vec<String> {
    let dep_tree = trace_dependency_tree(root, symbol_map, target_level + 1);
    dep_tree.into_iter()
        .filter(|(_, level)| *level == target_level)
        .map(|(name, _)| name)
        .collect()
}

fn analyze_resolution_status(
    dependencies: &[String],
    symbol_map: &HashMap<String, serde_json::Value>
) {
    println!("\n🔍 DEPENDENCY RESOLUTION ANALYSIS:");
    
    let mut resolved = 0;
    let mut unresolved = 0;
    
    for dep in dependencies.iter().take(20) {
        if symbol_map.contains_key(dep) {
            resolved += 1;
            println!("  ✅ {}", dep);
        } else {
            unresolved += 1;
            println!("  ❌ {}", dep);
        }
    }
    
    if dependencies.len() > 20 {
        println!("  ... and {} more dependencies", dependencies.len() - 20);
    }
    
    println!("\n📊 Resolution Summary:");
    println!("  ✅ Resolved: {}/{} ({:.1}%)", 
        resolved, dependencies.len(), 
        (resolved as f64 / dependencies.len() as f64) * 100.0);
    println!("  ❌ Unresolved: {}/{} ({:.1}%)", 
        unresolved, dependencies.len(),
        (unresolved as f64 / dependencies.len() as f64) * 100.0);
}

fn export_dependency_tree(root: &str, dep_tree: &HashMap<String, usize>) {
    let export_data = serde_json::json!({
        "root": root,
        "total_dependencies": dep_tree.len(),
        "max_depth": calculate_max_depth(dep_tree),
        "dependency_tree": dep_tree
    });
    
    let json_str = serde_json::to_string_pretty(&export_data).unwrap();
    std::fs::write("rustc_main_deps.json", json_str).unwrap();
    
    println!("\n📄 Exported rustc_main_deps.json");
}
